from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')
marker='ABEL_FUTURE_DESIGN_V1'
if marker in s:
    print('Redesign já aplicado')
    raise SystemExit(0)

css='''\n<!-- ABEL_FUTURE_DESIGN_V1 -->\n<style>\n:root{\n  --abel-bg:#081018;--abel-panel:rgba(15,23,33,.82);--abel-panel-2:rgba(19,29,41,.72);--abel-border:rgba(113,180,255,.14);--abel-text:#eef4f8;--abel-muted:#8e9ba8;--abel-gold:#d7ad39;--abel-cyan:#67d3ff;--abel-green:#38d39f;\n}\nhtml{background:#071018}\nbody{\n  background:\n    radial-gradient(circle at 14% 8%,rgba(64,126,255,.10),transparent 30%),\n    radial-gradient(circle at 84% 14%,rgba(215,173,57,.08),transparent 28%),\n    linear-gradient(180deg,#081018 0%,#0a121b 42%,#071018 100%)!important;\n  color:var(--abel-text);\n  min-height:100%;\n}\nbody:before{content:'';position:fixed;inset:0;pointer-events:none;opacity:.15;background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);background-size:32px 32px;mask-image:linear-gradient(to bottom,black,transparent 78%)}\nheader,.sticky,nav{backdrop-filter:blur(18px) saturate(140%);-webkit-backdrop-filter:blur(18px) saturate(140%)}\nheader{background:linear-gradient(180deg,rgba(9,16,24,.94),rgba(9,16,24,.78))!important;border-bottom:1px solid rgba(120,180,255,.08)}\n.rounded-xl,.rounded-2xl,[class*='border-[#']{box-shadow:inset 0 1px 0 rgba(255,255,255,.025),0 10px 30px rgba(0,0,0,.16)}\n.bg-\[\#111820\],.bg-\[\#101720\],.bg-\[\#121820\],.bg-\[\#0F141B\],.bg-\[\#151B23\]{background:linear-gradient(180deg,rgba(20,31,43,.88),rgba(12,20,30,.88))!important}\n.border-\[\#28313C\],.border-\[\#2A313B\],.border-\[\#2B313B\]{border-color:var(--abel-border)!important}\nbutton,a,[role='button']{transition:transform .18s ease,border-color .18s ease,background-color .18s ease,box-shadow .18s ease,opacity .18s ease}\n@media (hover:hover) and (pointer:fine){button:hover,a:hover,[role='button']:hover{transform:translateY(-1px)}}\nbutton:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid rgba(103,211,255,.55)!important;outline-offset:2px}\ninput,select,textarea{background:rgba(7,14,22,.78)!important;border-color:rgba(113,180,255,.16)!important;color:var(--abel-text)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.02)}\ninput:focus,select:focus,textarea:focus{border-color:rgba(103,211,255,.45)!important;box-shadow:0 0 0 3px rgba(103,211,255,.07)!important}\n.text-\[\#8A8F98\],.text-\[\#8A929E\],.text-\[\#747C88\]{color:var(--abel-muted)!important}\n.text-\[\#D5A928\]{color:#e2ba47!important;text-shadow:0 0 22px rgba(215,173,57,.14)}\n/* navegação */\nnav button,nav a{border-radius:10px!important;padding-top:.65rem!important;padding-bottom:.65rem!important}\nnav .active,[aria-current='page']{background:linear-gradient(180deg,rgba(215,173,57,.10),rgba(215,173,57,.035))!important;box-shadow:inset 0 -2px 0 rgba(215,173,57,.85),0 0 26px rgba(215,173,57,.05)!important}\n/* cartões e superfícies */\n[class*='rounded-xl'][class*='border'],[class*='rounded-2xl'][class*='border']{background-image:linear-gradient(180deg,rgba(255,255,255,.015),rgba(255,255,255,0));border-color:rgba(117,177,238,.13)!important}\n/* badges */\n[class*='bg-green'],[class*='bg-emerald']{box-shadow:0 0 20px rgba(56,211,159,.08)}\n/* scrollbars */\n*{scrollbar-width:thin;scrollbar-color:rgba(113,180,255,.22) transparent}\n*::-webkit-scrollbar{width:8px;height:8px}*::-webkit-scrollbar-track{background:transparent}*::-webkit-scrollbar-thumb{background:linear-gradient(180deg,rgba(103,211,255,.24),rgba(215,173,57,.18));border-radius:999px}\n/* mobile */\n@media(max-width:768px){body{background:linear-gradient(180deg,#081018,#09131d 55%,#071018)!important}header{backdrop-filter:blur(16px)}nav{gap:.15rem!important}.rounded-xl,.rounded-2xl{border-radius:14px!important}input,select,textarea{font-size:16px!important}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}\n</style>\n'''
if '</head>' not in s:
    raise SystemExit('head não encontrado')
s=s.replace('</head>',css+'\n</head>',1)
p.write_text(s,encoding='utf-8')
print('Redesign aplicado')
